class Solution {
public:
    int largestIsland(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<vector<int>> islandId(n, vector<int>(n, -1));
        vector<int> islandSize;
        int id = 0;
        int dx[4] = {0, 0, 1, -1};
        int dy[4] = {1, -1, 0, 0};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && islandId[i][j] == -1) {
                    int size = 0;
                    queue<pair<int,int>> q;
                    q.push({i, j});
                    islandId[i][j] = id;
                    while (!q.empty()) {
                        auto [x, y] = q.front();
                        q.pop();
                        size++;
                        for (int d = 0; d < 4; d++) {
                            int nx = x + dx[d], ny = y + dy[d];
                            if (nx >= 0 && nx < n && ny >= 0 && ny < n
                                && grid[nx][ny] == 1 && islandId[nx][ny] == -1) {
                                islandId[nx][ny] = id;
                                q.push({nx, ny});
                            }
                        }
                    }
                    islandSize.push_back(size);
                    id++;
                }
            }
        }

        if (id == 0) return 1;

        int maxIsland = *max_element(islandSize.begin(), islandSize.end());

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    set<int> neighbors;
                    for (int d = 0; d < 4; d++) {
                        int ni = i + dx[d], nj = j + dy[d];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n
                            && grid[ni][nj] == 1) {
                            neighbors.insert(islandId[ni][nj]);
                        }
                    }
                    int total = 1;
                    for (int nid : neighbors) {
                        total += islandSize[nid];
                    }
                    maxIsland = max(maxIsland, total);
                }
            }
        }

        return maxIsland;
    }
};
